from __future__ import annotations

from typing import Any

from orders.application.order_service import OrderService
from orders.controllers.http import Response, not_found
from orders.infrastructure.customers import InMemoryCustomerRepository
from orders.infrastructure.repository import InMemoryOrderRepository


class CustomerInsightsController:
    def __init__(self, customers: InMemoryCustomerRepository, orders: InMemoryOrderRepository,
                 order_service: OrderService) -> None:
        self._customers = customers
        self._orders = orders
        self._order_service = order_service

    def handle_order_history(self, customer_id: str) -> Response:
        if self._customers.get(customer_id) is None:
            return not_found("customer")

        orders = self._orders.list_for_customer(customer_id)
        order_entries = []
        for order in reversed(orders):
            summary = self._order_service.summarize(order)
            order_entries.append({
                "order_id": order.order_id,
                "status": order.status,
                "total_cents": summary.total_cents,
            })

        return Response(200, {
            "customer_id": customer_id,
            "orders": order_entries,
        })

